L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "<color=#ffd34c>\227\129\147\227\129\161\227\130\137\230\136\166\233\151\152\230\131\133\229\160\177\229\174\164\239\188\129\227\128\128\227\130\172\227\131\179\227\131\158\227\131\187\227\131\172\227\130\164\227\131\187\227\131\144\227\130\185\227\130\191\227\131\188\227\128\129\227\131\139\227\131\165\227\131\188\227\130\170\227\131\143\227\130\164\227\130\170\227\129\171\229\145\189\228\184\173\239\188\129</color>"
