L23_1 = "<color=#ffd34c>\224\184\153\224\184\181\224\185\136\224\184\130\224\185\136\224\184\178\224\184\167\224\184\129\224\184\163\224\184\173\224\184\135\224\184\168\224\184\182\224\184\129! \224\184\155\224\184\183\224\184\153\224\185\131\224\184\171\224\184\141\224\185\136\224\184\163\224\184\177\224\184\135\224\184\170\224\184\181\224\185\129\224\184\129\224\184\161\224\184\161\224\185\136\224\184\178\224\185\128\224\184\130\224\185\137\224\184\178\224\185\128\224\184\155\224\185\137\224\184\178\224\185\128\224\184\149\224\185\135\224\184\161\224\185\134!</color>"
