L22_1.m_Talk_VTN = L23_1
L23_1 = "<color=#ffd34c>\232\191\153\233\135\140\230\152\175\229\176\132\229\135\187\230\131\133\230\138\165\229\174\164\239\188\129\228\188\189\233\169\172\229\176\132\231\186\191\231\130\184\229\188\185\229\145\189\228\184\173\228\188\138\230\172\167\239\188\129</color>"
